module pc(clk, rst, next_pc, pc);
  input clk;
  wire clk;
  input [15:0] next_pc;
  wire [15:0] next_pc;
  output [15:0] pc;
  reg [15:0] pc = 16'h0000;
  input rst;
  wire rst;
  always @(posedge clk, posedge rst)
    if (rst) pc[0] <= 1'h0;
    else pc[0] <= next_pc[0];
  always @(posedge clk, posedge rst)
    if (rst) pc[1] <= 1'h0;
    else pc[1] <= next_pc[1];
