module status_register(clk, rst, latch_en, opcode_in, z_in, n_in, c_in, v_in, last_opcode, z, n, c, v);
  output c;
  reg c;
  input c_in;
  wire c_in;
  input clk;
  wire clk;
  output [6:0] last_opcode;
  reg [6:0] last_opcode;
  input latch_en;
  wire latch_en;
  output n;
  reg n;
  input n_in;
  wire n_in;
  input [6:0] opcode_in;
  wire [6:0] opcode_in;
  input rst;
  wire rst;
  output v;
  reg v;
  input v_in;
  wire v_in;
  output z;
  reg z;
  input z_in;
  wire z_in;
  always @(posedge clk, posedge rst)
    if (rst) last_opcode[0] <= 1'h0;
    else if (latch_en) last_opcode[0] <= opcode_in[0];
  always @(posedge clk, posedge rst)
    if (rst) last_opcode[1] <= 1'h0;
    else if (latch_en) last_opcode[1] <= opcode_in[1];
  always @(posedge clk, posedge rst)
    if (rst) last_opcode[2] <= 1'h0;
