  always @(posedge clk, posedge rst)
    if (rst) last_opcode[6] <= 1'h0;
    else if (latch_en) last_opcode[6] <= opcode_in[6];
  always @(posedge clk, posedge rst)
    if (rst) z <= 1'h0;
    else if (latch_en) z <= z_in;
  always @(posedge clk, posedge rst)
    if (rst) n <= 1'h0;
